  const aa101Text=__AI_ADVANCED_TEXTS__;
  const aa101Tools=[['query_transactions','agentToolQueryTransactions','agentToolQueryTransactionsDescription',false],['get_period_overview','agentToolTransactionSummary','agentToolTransactionSummaryDescription',false],['get_spending_trend','agentToolSpendingSummary','agentToolSpendingSummaryDescription',false],['get_category_breakdown','agentToolSpendingSummary','agentToolSpendingSummaryDescription',false],['get_budget_status','agentToolBudgetStatus','agentToolBudgetStatusDescription',false],['get_recurring_transactions','agentToolRecurringTransactions','agentToolRecurringTransactionsDescription',false],['record_transaction_from_text','agentToolRecordTransaction','agentToolRecordTransactionDescription',true],['save_explicit_memory','agentToolSaveMemory','agentToolSaveMemoryDescription',true],['forget_memory','agentToolForgetMemory','agentToolForgetMemoryDescription',true]];
  const aa101Routes={'advanced-memory':['agentMemoryTitle','agent_memory_page'],'advanced-memory-empty':['agentMemoryTitle','agent_memory_page'],'advanced-memory-loading':['agentMemoryTitle','agent_memory_page'],'advanced-memory-error':['agentMemoryTitle','agent_memory_page'],'advanced-memory-global':['agentMemoryTitle','agent_memory_page'],'advanced-permissions':['agentPermissionsTitle','agent_permissions_page'],'advanced-permissions-modified':['agentPermissionsTitle','agent_permissions_page'],'advanced-permissions-error':['agentPermissionsTitle','agent_permissions_page'],'advanced-activity':['agentActivityTitle','agent_activity_page'],'advanced-activity-empty':['agentActivityTitle','agent_activity_page'],'advanced-activity-error':['agentActivityTitle','agent_activity_page']};
  function aa101T(key,values={}){let value=aa101Text[key]||key;for(const[k,v]of Object.entries(values))value=value.replaceAll('{'+k+'}',String(v));return value;}
  function aa101Button(action,label,kind='bc-primary',disabled=false){return btn('aa101-'+action,esc(label),label,kind,disabled?'disabled':'');}
  function aa101Card(body){return `<section class="aa101-card">${body}</section>`;}
  function aa101Notice(text,glyph){return `<div class="aa101-notice">${icon(glyph)}<p>${esc(text)}</p></div>`;}
  function aa101Status(value){return aa101T(value==='ask'?'agentPermissionAsk':'agentPermissionAlwaysAllow');}
  function aa101Error(){return state.aa101Error?aa101Card(`<p class="aa101-error" role="status">${esc(state.aa101Error)}</p>${aa101Button('retry',aa101T('v4RecordingRetry'),'bc-secondary')}`):'';}
  function aa101Memory(key){if(key.endsWith('loading'))return `<div class="aa101-empty" role="status">${icon('loader-circle')}</div>`;return aa101Notice(aa101T('agentMemoryIntro'),'brain')+aa101Error()+(state.aa101Memories.length?`<div class="aa101-end">${aa101Button('clear',aa101T('agentMemoryClear'),'bc-secondary')}</div>`:`<p class="aa101-empty">${esc(aa101T('agentMemoryEmpty'))}</p>`)+state.aa101Memories.map(row=>aa101Card(`<div class="aa101-memory">${icon('bookmark')}<p>${esc(row.content)}</p><button data-action="aa101-forget-${row.id}" aria-label="${esc(aa101T('commonDelete'))}">${icon('trash-2')}</button></div>`)).join('');}
  function aa101Permissions(){if(state.aa101Error)return aa101Notice(aa101T('agentPermissionsIntro'),'info')+aa101Error();const count=aa101Tools.filter(([name,,,write])=>state.aa101Permissions[name]!== (write?'ask':'alwaysAllow')).length;return aa101Notice(aa101T('agentPermissionsIntro'),'info')+[false,true].map(write=>aa101Card(`<h3>${esc(aa101T(write?'agentPermissionsWriteSection':'agentPermissionsReadOnlySection'))}</h3><p class="aa101-muted">${esc(aa101T(write?'agentPermissionsWriteSectionDescription':'agentPermissionsReadOnlySectionDescription'))}</p>${aa101Tools.filter(x=>x[3]===write).map(([name,label,description])=>`<button class="aa101-permission" data-action="aa101-tool-${name}"><span><b>${esc(aa101T(label))}</b><small>${esc(aa101T(description))}</small></span><span class="aa101-status ${state.aa101Permissions[name]==='ask'?'warning':'success'}">${esc(aa101Status(state.aa101Permissions[name]))}</span></button>`).join('')}`)).join('')+aa101Card(`<p class="aa101-muted">${esc(count?aa101T('agentPermissionsModifiedCount',{count}):aa101T('agentPermissionsDefaultsActive'))}</p>${aa101Button('restore',aa101T('agentPermissionsRestoreDefaults'),'bc-secondary')}`);}
  function aa101Activity(key){return aa101Notice(aa101T('agentActivityIntro'),'history')+aa101Error()+(key.endsWith('empty')?`<p class="aa101-empty">${esc(aa101T('agentActivityEmpty'))}</p>`:state.aa101Error?'':[['completed','查询本月支出'],['cancelled','取消的请求'],['failed','失败的请求'],['running','执行中的请求']].map(([status,message])=>aa101Card(`<h3>${esc(message)}</h3><span class="aa101-status ${status==='completed'?'success':status==='failed'?'error':'warning'}">${esc(aa101T('agentActivity'+({completed:'Completed',cancelled:'Cancelled',failed:'Failed',running:'Running'})[status]))}</span>${status==='failed'?'<p class="aa101-muted">Synthetic run failure</p>':''}${status==='completed'?`<p class="aa101-muted">${esc(aa101T('agentActivityTools'))}</p><div class="aa101-tools">${['Completed','Denied','Failed'].map(tool=>`<span class="aa101-status ${tool==='Completed'?'success':tool==='Denied'?'warning':''}">${esc(aa101T('agentToolQueryTransactions'))} · ${esc(aa101T('agentActivityTool'+tool))}</span>`).join('')}</div>`:''}`)).join(''));}
  function aa101Modal(){const mode=state.aa101Modal;if(mode.startsWith('tool:')){const name=mode.slice(5),row=aa101Tools.find(x=>x[0]===name);return `<div class="aa101-overlay aa101-bottom"><section class="aa101-dialog" role="dialog" aria-modal="true"><h3>${esc(aa101T(row[1]))}</h3><p class="aa101-muted">${esc(aa101T(row[2]))}</p>${['ask','alwaysAllow'].map(value=>`<button class="aa101-option" data-action="aa101-option-${value}" aria-pressed="${state.aa101Permissions[name]===value}">${esc(aa101Status(value))}${state.aa101Permissions[name]===value?icon('check'):''}</button>`).join('')}${aa101Button('close',aa101T('commonCancel'),'bc-secondary')}</section></div>`;}
    const clear=mode==='clear',restore=mode==='restore',title=aa101T(restore?'agentPermissionsRestoreTitle':clear?'agentMemoryClearTitle':'agentMemoryDeleteTitle'),message=aa101T(restore?'agentPermissionsRestoreDescription':clear?'agentMemoryClearDescription':'agentMemoryDeleteDescription');return `<div class="aa101-overlay"><section class="aa101-dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><h3>${esc(title)}</h3><p>${esc(message)}</p><div class="aa101-actions">${aa101Button('close',aa101T('commonCancel'),'bc-secondary')}${aa101Button('confirm',aa101T(restore?'agentPermissionsRestoreConfirm':'commonDelete'))}</div></section></div>`;}
  function aa101Page(key){return `<div class="aa101-shell">${key.startsWith('advanced-memory')?aa101Memory(key):key.startsWith('advanced-permissions')?aa101Permissions():aa101Activity(key)}${state.aa101Modal?aa101Modal():''}</div>`;}
  for(const[key,[title,source]]of Object.entries(aa101Routes))fDefine(key,aa101T(title),'AI高级设置','ai/'+source+'.dart',()=>aa101Page(key));
  const aa101Before=fRender;
  fRender=function(key){if(!Object.hasOwn(aa101Routes,key))return aa101Before(key);if(state.aa101Preset!==key){Object.assign(state,{aa101Preset:key,aa101Modal:'',aa101Error:key.endsWith('error')?aa101T(key.startsWith('advanced-permissions')?'agentPermissionWriteFailed':'commonFailed'):'',aa101Memories:key.endsWith('empty')?[]:[{id:'own',content:'午饭优先使用现金账户',ledger:1}],aa101Permissions:Object.fromEntries(aa101Tools.map(([name,,,write])=>[name,write?'ask':'alwaysAllow']))});if(key.endsWith('global'))state.aa101Memories.push({id:'global',content:'Global preference',ledger:null});if(key.endsWith('modified'))state.aa101Permissions.record_transaction_from_text='alwaysAllow';}return subhead(aa101T(aa101Routes[key][0]))+aa101Page(key);};
  document.addEventListener('click',event=>{const action=event.target.closest('[data-action]')?.dataset.action;if(!action?.startsWith('aa101-'))return;event.preventDefault();event.stopImmediatePropagation();const command=action.slice(6);if(command==='close')state.aa101Modal='';else if(command==='retry')state.aa101Error='';else if(['clear','restore'].includes(command))state.aa101Modal=command;else if(command.startsWith('forget-'))state.aa101Modal='forget:'+command.slice(7);else if(command.startsWith('tool-'))state.aa101Modal='tool:'+command.slice(5);else if(command.startsWith('option-')&&state.aa101Modal.startsWith('tool:')){state.aa101Permissions[state.aa101Modal.slice(5)]=command.slice(7);state.aa101Modal='';}else if(command==='confirm'){const mode=state.aa101Modal;if(mode==='restore')state.aa101Permissions=Object.fromEntries(aa101Tools.map(([name,,,write])=>[name,write?'ask':'alwaysAllow']));else if(mode==='clear')state.aa101Memories=state.aa101Memories.filter(x=>x.ledger!==1);else if(mode.startsWith('forget:')){const id=mode.slice(7),row=state.aa101Memories.find(x=>x.id===id);if(row?.ledger!==1)state.aa101Error=aa101T('commonFailed');else state.aa101Memories=state.aa101Memories.filter(x=>x.id!==id);}state.aa101Modal='';}render();},true);
